/* socket_creation_example.c */
#include <stdio.h>
#include <sys/socket.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

int main() {
    int tcp_socket_fd;

    // Parameters for a standard IPv4 TCP socket:
    // Domain: AF_INET (IPv4)
    // Type: SOCK_STREAM (Connection-oriented, TCP)
    // Protocol: 0 (Default protocol)
    tcp_socket_fd = socket(AF_INET, SOCK_STREAM, 0);

    if (tcp_socket_fd == -1) {
        // Error handling based on errno
        perror("Error creating socket");
        return EXIT_FAILURE;
    }

    printf("Successfully created socket file descriptor: %d\n", tcp_socket_fd);

    // A server would next call bind() and listen().
    // A client would next call connect().

    // Proper cleanup
    if (close(tcp_socket_fd) == -1) {
        perror("Error closing socket");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
